export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed, g = 9.8;
  const T = 2 * u / g;
  const t = Math.max(0, Math.min(time, T));
  const v = u - g * t;
  const h = u * t - g * t * t / 2;
  const apexTime = u / g, apexHeight = u * u / (2 * g);
  const base = 360, top = 80;
  const sc = (base - top) / 1.4;
  const bx = 300;
  const by = base - h * sc;
  const eps = 0.005;
  const state = Math.abs(v) < eps ? 'Still for an instant' : (v > 0 ? 'Moving up' : 'Moving down');
  const objs = [];
  objs.push(...sdk.panel({ id: 'lane.toss', x: 20, y: 40, w: 600, h: 370, title: 'Vertical toss', state: state }));
  objs.push(sdk.line('guide.launch', 200, base + 12, 400, base + 12, { role: 'neutral' }));
  objs.push(sdk.text('guide.label', 410, base + 17, 'Launch height', { role: 'neutral' }));
  objs.push(sdk.circle('ball.toss', bx, by, 24, { role: 'observed' }));
  objs.push(...sdk.vector('vec.v', { x: bx + 50, y: by }, { value: Math.abs(v) < eps ? 0 : v, direction: 'up' }, { scale: 20, minLength: 12, label: 'v', role: 'input' }));
  objs.push(...sdk.vector('vec.a', { x: bx - 50, y: by }, { value: -g, direction: 'up' }, { scale: 6, minLength: 12, label: 'a', role: 'warning' }));
  objs.push(...sdk.callout(440, 150, [state, 'Gravity pulls down'], { id: 'callout.toss' }));
  return {
    frame: { width: 640, height: 420, objects: objs, readouts: [{ id: 'motionState', value: state }, { id: 'gravityState', value: 'Gravity pulls down' }] },
    quantities: { launchSpeed: u, gravity: g, apexTime, apexHeight, velocity: v, height: h }
  };
}
